'use strict';
(()=>{let state,draft={},groups=[],detail=null,busy=false;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),labels={draft:'مسودة',reviewed:'تمت مراجعة المستلمين',archived:'مؤرشفة',ready:'جاهز · لم يُرسل',excluded:'مستبعد',accepted:'قُبل طلب الإرسال',delivered:'تم التسليم',read:'مقروء',failed:'فشل',unconfirmed:'غير مؤكد'};
const say=t=>document.querySelector('#marketing-alert').textContent=t;
async function api(path,b){const r=await fetch('/api/marketing/'+path,{credentials:'same-origin',cache:'no-store',...(b?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'تعذر تنفيذ الطلب.');return d;}
const field=(n,l,v='',extra='')=>`<label>${l}<input name="${n}" value="${esc(v)}" ${extra}></label>`;
const option=(id,t,current)=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(t)}</option>`;
function keep(){const f=document.querySelector('#campaign-editor');if(!f)return;const d=Object.fromEntries(new FormData(f));draft={...draft,title:d.title,templateId:d.templateId,audience:{...draft.audience,business:d.business,group:d.group,card:d.card,branch:d.branch},parameters:[...f.querySelectorAll('[data-campaign-param]')].map(x=>x.value)};}
function editor(){const a=draft.audience||{business:'platform'},businesses=[...new Map(state.catalog.map(c=>[c.business,c])).values()],cards=state.catalog.filter(c=>c.business===a.business),branches=cards.flatMap(c=>c.branches||[]),t=state.templates.find(x=>x.id===draft.templateId),indices=[...new Set([...(t?.body||'').matchAll(/\{\{(\d+)\}\}/g)].map(m=>+m[1]))].sort((a,b)=>a-b);
return `<div class="template-workspace"><section class="marketing-panel"><div class="section-heading"><h2>${draft.id?'تعديل الحملة':'إنشاء حملة'}</h2><button type="button" class="info-button" data-campaign="new">حملة جديدة</button></div><p>١ اختر القالب · ٢ اختر المجموعة · ٣ راجع الأرقام · ٤ الإرسال بعد الربط.</p><form id="campaign-editor">${field('title','اسم الحملة',draft.title,'required maxlength="100" placeholder="مثال: عرض نهاية الأسبوع — فرع الرياض"')}<label>القالب<select name="templateId" required><option value="">اختر قالبًا محفوظًا</option>${state.templates.map(t=>option(t.id,t.title+' · '+t.language,draft.templateId)).join('')}</select></label><div class="form-row"><label>النشاط<select name="business">${option('platform','أرقام مستقلة · رجعة',a.business||'platform')}${businesses.map(c=>option(c.business,c.name,a.business)).join('')}</select></label><label>المجموعة<select name="group">${option('','جميع الأرقام',a.group||'')}${option('ungrouped','بدون مجموعة',a.group)}${groups.filter(g=>!g.archived).map(g=>option(g.id,g.name+' · '+g.count+' رقم',a.group)).join('')}</select></label></div><div class="form-row"><label>بطاقة الولاء · اختياري<select name="card">${option('','جميع البطاقات',a.card||'')}${cards.map(c=>option(c.id,c.name,a.card)).join('')}</select></label><label>الفرع · اختياري<select name="branch">${option('','جميع الفروع',a.branch||'')}${branches.map(c=>option(c.id,c.name,a.branch)).join('')}</select></label></div>${a.selected?.length?`<p>${a.selected.length} رقم محدد من جهات الاتصال. تتقاطع المجموعة والتصفية مع هذه الأرقام.<button type="button" class="info-button" data-campaign="clear-selection">استخدام كامل المجموعة</button></p>`:''}${indices.map((i,j)=>field('param'+i,'قيمة المتغير {{'+i+'}}',draft.parameters?.[j]||'','required maxlength="1000" data-campaign-param placeholder="اكتب قيمة ثابتة أو @name لاسم العميل"')).join('')}<p>استخدم <b dir="ltr">@name</b> لاسم كل عميل. الصورة والأزرار من القالب المحفوظ.</p><button class="info-button gold">حفظ الحملة</button></form></section><aside class="template-preview-panel"><h2>معاينة رسالة الحملة</h2><div id="campaign-message-preview">${t?window.MarketingTemplateEditor.preview({...t,samples:indices.map((v,i)=>draft.parameters?.[i]==='@name'?'أحمد':draft.parameters?.[i]||t.samples?.[i])}):'<p>اختر القالب لعرض الصورة والنص والأزرار.</p>'}</div></aside></div>`;}
function details(){if(!detail)return '';const d=detail;return `<section class="marketing-panel"><div class="section-heading"><div><h2>${esc(d.title)}</h2><p>${esc(d.template?.name||state.templates.find(t=>t.id===d.templateId)?.name||'—')} · ${esc(d.groupName||'جميع الأرقام')} · ${labels[d.status]}</p></div><button class="info-button" data-campaign="close">إغلاق التفاصيل</button></div><div class="campaign-stats"><span>المستلمون <b>${d.total||0}</b></span><span>جاهزون <b>${d.eligible||0}</b></span><span>مستبعدون <b>${d.excluded||0}</b></span><span>مرسلة <b>${d.recipients.filter(r=>r.messageId).length}</b></span></div><p>${d.reviewedAt?'المراجعة: '+new Date(d.reviewedAt).toLocaleString('ar-SA')+' · قائمة محفوظة وقت المراجعة. أعد المراجعة بعد تعديل المجموعة.':'راجع المجموعة لتثبيت قائمة المستلمين قبل الإرسال.'}</p><div class="marketing-actions"><button class="info-button gold" data-campaign="review" data-id="${esc(d.id)}" ${d.status==='archived'?'disabled':''}>مراجعة المستلمين</button><button class="info-button" data-campaign="export" ${!d.recipients.length?'disabled':''}>تنزيل سجل المستلمين</button><button class="info-button" disabled>إرسال الحملة · بعد الربط</button></div><p>لم يُرسل شيء. لاحقًا يميّز السجل قبول الطلب والتسليم والقراءة والفشل؛ لا تُحسب الرسالة مسلّمة بمجرد قبول الطلب.</p><label>تصفية السجل<select id="campaign-status-filter"><option value="">كل الحالات</option><option value="ready">جاهزون</option><option value="excluded">مستبعدون</option></select></label><div class="campaign-recipient-table"><table class="marketing-table"><thead><tr><th>الاسم</th><th>الجوال</th><th>الحالة</th><th>السبب</th><th>معرّف الرسالة</th></tr></thead><tbody>${d.recipients.map(r=>`<tr data-recipient-status="${esc(r.status)}"><td>${esc(r.name||'—')}</td><td dir="ltr">${esc(r.phone)}</td><td>${labels[r.status]||esc(r.status)}</td><td>${esc(r.reason||'—')}</td><td>${esc(r.messageId||'—')}</td></tr>`).join('')||'<tr><td colspan="5">احفظ الحملة ثم راجع المستلمين.</td></tr>'}</tbody></table></div></section>`;}
function library(){return `<section class="marketing-panel"><h2>حملاتك وسجلها</h2><div class="template-library">${state.campaigns.map(d=>`<article class="template-library-card"><b>${esc(d.title)}</b><span class="marketing-status">${labels[d.status]}</span><p>القالب: ${esc(state.templates.find(t=>t.id===d.templateId)?.title||'—')}<br>المجموعة: ${esc(d.groupName||'جميع الأرقام')}<br>${d.total||0} مستلم · ${d.eligible||0} جاهز · ${d.excluded||0} مستبعد</p><div class="marketing-actions"><button class="info-button" data-campaign="detail" data-id="${esc(d.id)}">التفاصيل والسجل</button><button class="info-button" data-campaign="edit" data-id="${esc(d.id)}" ${d.status==='archived'?'disabled':''}>تعديل</button><button class="info-button" data-campaign="archive" data-id="${esc(d.id)}">${d.status==='archived'?'استعادة':'أرشفة'}</button></div></article>`).join('')||'<p>ابدأ بحملة واربطها بقالب ومجموعة.</p>'}</div>${state.legacyCampaigns?.length?'<p>المسودات القديمة محفوظة؛ أنشئ حملة من المحرر الجديد لربط القالب والمجموعة.</p>':''}</section>`;}
function render(){const root=document.querySelector('#marketing-campaign-root');if(root)root.innerHTML=editor()+details()+library();}
async function loadGroups(){groups=(await api('contacts?business='+encodeURIComponent(draft.audience?.business||'platform'))).groups;render();}
async function run(fn){if(busy)return;busy=true;try{await fn();}catch(e){say(e.message);}finally{busy=false;}}
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='campaign-editor')return;e.preventDefault();keep();run(async()=>{const g=groups.find(g=>g.id===draft.audience.group);const r=await api('campaign-save',{...draft,groupName:g?.name|| (draft.audience.group==='ungrouped'?'بدون مجموعة':'جميع الأرقام')});draft=r.campaign;detail=r.campaign;state=await api('state');render();say('حُفظت الحملة. راجع المستلمين قبل الإرسال.');});});
document.addEventListener('change',e=>{if(e.target.id==='campaign-status-filter'){document.querySelectorAll('[data-recipient-status]').forEach(r=>r.hidden=!!e.target.value&&r.dataset.recipientStatus!==e.target.value);return;}if(!e.target.closest('#campaign-editor'))return;keep();if(e.target.name==='business'){draft.audience={business:e.target.value};run(loadGroups);}else if(e.target.name==='templateId'){draft.parameters=[];render();}});
document.addEventListener('input',e=>{if(e.target.closest('#campaign-editor')){keep();const t=state.templates.find(x=>x.id===draft.templateId),p=document.querySelector('#campaign-message-preview');if(t&&p)p.innerHTML=window.MarketingTemplateEditor.preview({...t,samples:draft.parameters.map(v=>v==='@name'?'Ahmed':v)});}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-campaign]');if(!b||b.disabled)return;run(async()=>{const a=b.dataset.campaign;if(a==='new'){draft={};detail=null;await loadGroups();}if(a==='clear-selection'){keep();draft.audience.selected=[];render();}if(a==='close'){detail=null;render();}if(a==='detail'){detail=(await api('campaign-detail?id='+encodeURIComponent(b.dataset.id))).campaign;render();}if(a==='edit'){draft=(await api('campaign-detail?id='+encodeURIComponent(b.dataset.id))).campaign;detail=draft;await loadGroups();}if(a==='review'){detail=(await api('campaign-review',{id:b.dataset.id})).campaign;state=await api('state');render();say('تمت مراجعة الأرقام؛ لم تُرسل رسائل.');}if(a==='archive'){const d=state.campaigns.find(d=>d.id===b.dataset.id);await api('campaign-archive',{id:d.id,archived:d.status!=='archived'});state=await api('state');detail=null;if(draft.id===d.id)draft={};render();}if(a==='export'){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';},rows=[['الحملة','المجموعة','القالب','الاسم','الجوال','الحالة','السبب','معرف الرسالة'],...detail.recipients.map(r=>[detail.title,detail.groupName,detail.template?.name,r.name,r.phone,labels[r.status],r.reason,r.messageId])],url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='campaign-recipients.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});});
window.MarketingCampaigns={keep,html:s=>{state=s;return '<div id="marketing-campaign-root">جارٍ تحميل الحملات…</div>';},init:()=>loadGroups().catch(e=>say(e.message)),audience:a=>{draft={audience:a};detail=null;},reset:()=>{draft={};detail=null;}};
})();
